page(pid, "TTHM and HAA5 MCL compliance calculation: locational running annual average (LRAA) under subpart V, running annual average (RAA) under subpart L, and increased monitoring", APP_LV, ["141.2", "141.620", "141.625", "141.133"], qs, cs)

# ---------- page 8: operational evaluation levels ----------
pid = "dbp.compliance.oel"
S626_A = "(a) You have exceeded the operational evaluation level at any monitoring location where the sum of the two previous quarters' TTHM results plus twice the current quarter's TTHM result, divided by 4 to determine an average, exceeds 0.080 mg/L, or where the sum of the two previous quarters' HAA5 results plus twice the current quarter's HAA5 result, divided by 4 to determine an average, exceeds 0.060 mg/L."
S626_B1 = "(b)(1) If you exceed the operational evaluation level, you must conduct an operational evaluation and submit a written report of the evaluation to the State no later than 90 days after being notified of the analytical result that causes you to exceed the operational evaluation level. The written report must be made available to the public upon request."
S626_B2 = "(2) Your operational evaluation must include an examination of system treatment and distribution operational practices, including storage tank operations, excess storage capacity, distribution system flushing, changes in sources or source water quality, and treatment changes or problems that may contribute to TTHM and HAA5 formation and what steps could be considered to minimize future exceedances."
S626_B2_LIMIT = "(i) You may request and the State may allow you to limit the scope of your evaluation if you are able to identify the cause of the operational evaluation level exceedance. (ii) Your request to limit the scope of the evaluation does not extend the schedule in paragraph (b)(1) of this section for submitting the written report. The State must approve this limited scope of evaluation in writing and you must keep that approval with the completed report."
S620_NOTE1 = "1 The State may grant up to an additional 24 months for compliance with MCLs and operational evaluation levels if you require capital improvements to comply with an MCL."
qs = [quote(pid, "oel-exceedance", "141.626", S626_A), quote(pid, "evaluation-and-report", "141.626", S626_B1), quote(pid, "evaluation-content", "141.626", S626_B2), quote(pid, "limited-scope", "141.626", S626_B2_LIMIT),
      quote(pid, "applicability", "141.620", S620_B), quote(pid, "schedule-extension", "141.620", S620_NOTE1)]
SHARED = ["applicability"]   # 141.620(b) subpart V scope, on every claim
COND_FORMULA = ["Computed at each monitoring location as the sum of the two previous quarters' results plus twice the current quarter's result, divided by 4 (in symbols, (Q1 + Q2 + 2 Q3) / 4 with Q3 the current quarter); the computation uses that location's quarterly results",
                "TTHM and HAA5 are evaluated separately; exceeding either level is an operational evaluation level exceedance"]
cs = [claim(pid, "oel-tthm", "numeric", "Operational evaluation level (OEL) for TTHM at a monitoring location", "gt", "other", 0.080, ["oel-exceedance"] + SHARED, APP_LV, COND_FORMULA, unit="mg/L"),
      claim(pid, "oel-haa5", "numeric", "Operational evaluation level (OEL) for HAA5 at a monitoring location", "gt", "other", 0.060, ["oel-exceedance"] + SHARED, APP_LV, COND_FORMULA, unit="mg/L"),
      claim(pid, "oel-computation", "qualitative", "Operational evaluation level (OEL) formula and computation", "eq", "other",
            "At any monitoring location: the two previous quarters' results plus twice the current quarter's result, divided by 4 to determine an average, for TTHM and for HAA5; the level is exceeded where that average exceeds 0.080 mg/L for TTHM or 0.060 mg/L for HAA5", ["oel-exceedance"] + SHARED, APP_LV,
            ["The terms, in the source's words: the two previous quarters' results, the current quarter's result (counted twice), and the divisor 4; 141.626 names no symbols, and OEL is the editorial abbreviation for operational evaluation level"]),
      claim(pid, "applies-to", "qualitative", "Systems and locations to which operational evaluation level (OEL) requirements apply", "required", "other",
            "Systems subject to subpart V (community and nontransient noncommunity water systems that use, or deliver water treated with, a primary or residual disinfectant other than ultraviolet light), at any monitoring location, computed from that location's two previous quarters' results and the current quarter's result", ["applicability", "oel-exceedance"] + SHARED, APP_LV,
            ["141.626 states no purpose for operational evaluation levels; a purpose is not asserted by this page"]),
      claim(pid, "evaluation-required", "qualitative", "Operational evaluation after an exceedance", "required", "other",
            "Conduct an operational evaluation and submit a written report of it to the State no later than 90 days after being notified of the analytical result that caused the exceedance; the written report must be made available to the public upon request", ["evaluation-and-report"] + SHARED, APP_LV),
      claim(pid, "report-deadline-days", "numeric", "Deadline for the written operational evaluation report to the State", "lte", "other", 90, ["evaluation-and-report"] + SHARED, APP_LV,
            ["Counted from being notified of the analytical result that causes the exceedance; a request to limit the evaluation's scope does not extend this schedule (141.626(b)(2)(ii))"], unit="days"),
      claim(pid, "evaluation-content", "qualitative", "Required content of the operational evaluation", "required", "other",
            "An examination of system treatment and distribution operational practices, including storage tank operations, excess storage capacity, distribution system flushing, changes in sources or source water quality, and treatment changes or problems that may contribute to TTHM and HAA5 formation, and what steps could be considered to minimize future exceedances", ["evaluation-content"] + SHARED, APP_LV),
      claim(pid, "limited-scope", "qualitative", "Limiting the scope of the operational evaluation", "eq", "other",
            "A system may request, and the State may allow, a limited-scope evaluation when the system can identify the cause of the exceedance; the State's approval must be in writing and kept with the completed report, and the request does not extend the 90-day report schedule", ["limited-scope", "evaluation-and-report"] + SHARED, APP_LV),
      claim(pid, "schedule-extension", "qualitative", "State extension of the subpart V schedule for operational evaluation levels", "eq", "other",
            "The State may grant up to an additional 24 months for compliance with MCLs and operational evaluation levels where capital improvements are required to comply with an MCL", ["schedule-extension"] + SHARED, APP_LV,
            ["Footnote 1 to the compliance schedule table in 141.620(c)"])]
page(pid, "Operational evaluation levels (OEL) for TTHM and HAA5: the OEL formula, exceedance, operational evaluation and written report", APP_LV, ["141.626", "141.620"], qs, cs)
